import json,sys
for f in ['docs/specs/workspace.json','docs/specs/matrix.json']:
    d=json.load(open(f))
    print('=====',f, list(d.keys()))
    for k in d:
        if k not in ('acceptance_criteria','criteria','reasoning'): print(k, json.dumps(d[k])[:1500])
    ac=d.get('acceptance_criteria') or d.get('criteria')
    for c in ac: print(json.dumps(c))
"

