174	/// Extracts `[tool.maturin].targets` from an already-parsed `pyproject.toml`
175	/// value (see `parse_pyproject_toml`). Returns `Ok(None)` when the table or
176	/// field is absent (no platformTargets entry). A present value that
177	/// is not a TOML array of strings is a hard error.
178	pub(crate) fn read_maturin_targets(
179	    pyproject_path: &Path,
180	    val: &toml::Value,
181	) -> Result<Option<Vec<String>>, GraphError> {
182	    let Some(targets) = val
183	        .get("tool")
184	        .and_then(|t| t.get("maturin"))
185	        .and_then(|m| m.get("targets"))
186	    else {
187	        return Ok(None);
188	    };
189	
190	    let arr = targets.as_array().ok_or_else(|| {
191	        GraphError::Manifest(ManifestError::Parse {
192	            path: pyproject_path.to_path_buf(),
193	            format: ManifestFormat::PyprojectToml,
194	            message: "[tool.maturin].targets must be an array of strings".to_string(),
195	        })
196	    })?;
197	
198	    let mut out = Vec::with_capacity(arr.len());
199	    for item in arr {
200	        let s = item.as_str().ok_or_else(|| {
201	            GraphError::Manifest(ManifestError::Parse {
202	                path: pyproject_path.to_path_buf(),
203	                format: ManifestFormat::PyprojectToml,
204	                message: "[tool.maturin].targets entries must all be strings".to_string(),
205	            })
206	        })?;
207	        out.push(s.to_string());
208	    }
209	    Ok(Some(out))
210	}
