248	/// Reads napi.targets and [tool.maturin].targets from `package_dir_abs`
249	/// (the package's on-disk directory) and determines which single source (if
250	/// any) declares platform targets.
251	///
252	/// `pkg_json_val`/`pyproject_val` are the package's already-parsed manifest
253	/// values (see `parse_package_json`/`parse_pyproject_toml`), `None` when the
254	/// corresponding file doesn't exist -- shared with `assemble_runtime_versions`
255	/// so `build_matrix_report` parses each file at most once per package.
256	///
257	/// - Neither declared: `Ok(None)`.
258	/// - Both declared: `Err(GraphError::ConflictingPlatformTargetSources)`.
259	/// - Exactly one declared (even as an explicitly empty array):
260	///   `Ok(Some((kind, source, triples)))`.
261	pub(crate) fn select_platform_target_source(
262	    package_dir_abs: &Path,
263	    package_id: &PackageId,
264	    pkg_json_val: Option<&serde_json::Value>,
265	    pyproject_val: Option<&toml::Value>,
266	) -> Result<Option<(PlatformTargetKind, String, Vec<String>)>, GraphError> {
267	    let napi_path = package_dir_abs.join("package.json");
268	    let napi_field = match pkg_json_val {
269	        Some(val) => read_napi_targets(&napi_path, val)?,
270	        None => NapiTargetsField::Absent,
271	    };
272	
273	    let maturin_path = package_dir_abs.join("pyproject.toml");
274	    let maturin_targets = match pyproject_val {
275	        Some(val) => read_maturin_targets(&maturin_path, val)?,
276	        None => None,
277	    };
278	
279	    match (napi_field, maturin_targets) {
280	        (NapiTargetsField::Present(_), Some(_)) => Err(GraphError::ConflictingPlatformTargetSources {
281	            package: package_id.clone(),
282	            napi_source: "napi.targets",
283	            maturin_source: "[tool.maturin].targets",
284	        }),
285	        (NapiTargetsField::Present(triples), None) => {
286	            Ok(Some((PlatformTargetKind::Napi, "napi.targets".to_string(), triples)))
287	        }
288	        (NapiTargetsField::Absent, Some(triples)) => Ok(Some((
289	            PlatformTargetKind::Maturin,
290	            "[tool.maturin].targets".to_string(),
291	            triples,
292	        ))),
293	        (NapiTargetsField::Absent, None) => Ok(None),
294	    }
295	}
