        let json = r#"{"napi":{"binaryName":"addon"}}"#;
        for lib in ["addon", "other_name"] {
            let crates = [
                napi_crate(lib, "packages/napi/Cargo.toml"),
                napi_crate("addon", "crates/addon/Cargo.toml"),
