11	pub struct MatrixOptions {
12	    /// When Some, restrict the report to exactly this one registered package.
13	    /// Accepts a bare name -- resolved only when it matches exactly one
14	    /// registered package (`GraphError::AmbiguousName` otherwise, listing
15	    /// the qualified candidates) -- or an ecosystem-qualified id
16	    /// (`cargo/foo`, `npm/foo`). Err(GraphError::UnknownPackage) when no
17	    /// registered package matches. Resolved through
18	    /// [`crate::IdentityIndex::resolve`], the one selector resolver shared
19	    /// with every other package-selecting surface.
20	    pub package: Option<String>,
21	    /// Resolve each napi package's addon crate into `manifestPath` (E204 when not exactly one).
