25	pub fn matrix<R: CommandRunner, D: DependencyResolver>(
26	    ws: &Workspace<'_, R, D>,
27	    opts: &MatrixOptions,
28	) -> Result<MatrixReport, GraphError> {
29	    let all_packages: Vec<&callisto_model::Package> = ws.graph.packages().collect();
30	
31	    let selected = opts
32	        .package
33	        .as_deref()
34	        .map(|raw| resolve_selected_package(&all_packages, &ws.identity, raw))
35	        .transpose()?;
36	
37	    let inputs: Vec<MatrixPackageInput> = all_packages
38	        .iter()
39	        .filter(|p| selected.as_ref().is_none_or(|id| p.id == *id))
40	        .map(|p| {
41	            let dir_rel = package_dir_rel(p);
42	            MatrixPackageInput {
43	                id: p.canonical_id(),
44	                dir_abs: ws.root.join(&dir_rel),
45	                dir_rel,
46	                name: p.id.name().to_string(),
47	            }
48	        })
49	        .collect();
50	
51	    let napi_crates = opts
52	        .napi_crates
53	        .then(|| workspace_napi_crates(ws, &all_packages))
54	        .transpose()?;
55	    let mut report = build_matrix_report(&inputs, napi_crates.as_deref())?;
56	    let mut artifacts = Vec::new();
57	    for artifact in ws
58	        .config
59	        .product_release
60	        .iter()
61	        .flat_map(|release| &release.artifacts)
62	        .filter(|artifact| artifact.package.ecosystem() == Some(callisto_model::Ecosystem::Cargo))
63	        .filter(|artifact| {
64	            selected
65	                .as_ref()
66	                .is_none_or(|id| ws.identity.identifies(&artifact.package, id))
67	        })
68	    {
69	        let resolved = all_packages.iter().find_map(|package| {
70	            let manifest = package
71	                .canonical_manifests()
72	                .find(|manifest| manifest.ecosystem() == callisto_model::Ecosystem::Cargo)?;
73	            ws.identity
74	                .identifies(&artifact.package, &package.id)
75	                .then_some((package, manifest))
76	        });
77	        let Some((package, manifest)) = resolved else {
78	            report.diagnostics.push(Diagnostic {
79	                code: DiagnosticCode::UnknownPackage,
80	                severity: DiagnosticSeverity::Warning,
81	                message: format!(
82	                    "`[[release.artifact]]` package `{}` (asset `{}`) is not a cargo package in this workspace; it has no matrix entry",
83	                    artifact.package, artifact.asset_name
84	                ),
85	                package: Some(artifact.package.clone()),
86	                path: None,
87	                escalated_by: None,
88	                governed_by: None,
89	            });
90	            continue;
91	        };
92	        artifacts.push(ReleaseArtifactInput {
93	            id: package.canonical_id(),
94	            name: package.id.name().to_string(),
95	            dir_rel: manifest
96	                .path
97	                .parent()
98	                .map(|dir| dir.to_string_lossy().to_string())
99	                .unwrap_or_default(),
100	            target: artifact.target.clone(),
101	            asset_name: artifact.asset_name.clone(),
102	        });
103	    }
104	    add_release_artifact_groups(&mut report, &artifacts)?;
105	    Ok(report)
106	}
