125	/// Every workspace cargo package that builds a napi-rs addon.
126	fn workspace_napi_crates<R: CommandRunner, D: DependencyResolver>(
127	    ws: &Workspace<'_, R, D>,
128	    packages: &[&callisto_model::Package],
129	) -> Result<Vec<NapiCrate>, GraphError> {
130	    let ctx = callisto_manifests::OpenContext::for_workspace_root(&ws.root)?;
131	    let mut crates = Vec::new();
132	    for decl in packages
133	        .iter()
134	        .flat_map(|package| package.canonical_manifests())
135	        .filter(|decl| decl.format == callisto_model::ManifestFormat::CargoToml)
136	    {
137	        if let Some(lib_name) = crate::manifest_cache::open_cached(&ws.manifest_cache, decl, &ctx)?.napi_lib_name() {
138	            crates.push(NapiCrate {
139	                lib_name,
140	                manifest_path: decl.path.to_string_lossy().into_owned(),
141	            });
142	        }
143	    }
144	    Ok(crates)
145	}
