416	/// Reads engines.node (npm) and requires-python (python) from
417	/// `package_dir_abs`'s already-parsed manifest values, in that order, so
418	/// callers preserve the npm-before-python ordering without
419	/// a separate sort step. `pkg_json_val`/`pyproject_val` are shared with
420	/// `assemble_platform_target_group` (see `select_platform_target_source`'s
421	/// doc comment) so `build_matrix_report` parses each file at most once per
422	/// package.
423	pub(crate) fn assemble_runtime_versions(
424	    package_dir_abs: &Path,
425	    pkg_json_val: Option<&serde_json::Value>,
426	    pyproject_val: Option<&toml::Value>,
427	) -> Result<Vec<RuntimeVersionEntry>, GraphError> {
428	    let mut entries = Vec::new();
429	
430	    let pkg_json = package_dir_abs.join("package.json");
431	    if let Some(val) = pkg_json_val
432	        && let Some(range) = read_engines_node(&pkg_json, val)?
433	    {
434	        entries.push(RuntimeVersionEntry {
435	            ecosystem: RuntimeEcosystem::Npm,
436	            field: "engines.node".to_string(),
437	            range,
438	        });
439	    }
440	
441	    let pyproject = package_dir_abs.join("pyproject.toml");
442	    if let Some(val) = pyproject_val
443	        && let Some(range) = read_requires_python(&pyproject, val)?
444	    {
445	        entries.push(RuntimeVersionEntry {
446	            ecosystem: RuntimeEcosystem::Python,
447	            field: "requires-python".to_string(),
448	            range,
449	        });
450	    }
451	
452	    Ok(entries)
453	}
