/// A napi package and a maturin package that both
/// declare the same two triples must produce byte-identical platform/arch/
/// abi/hostRunner/useCross for each triple -- proving the derivation is
/// shared code, not a duplicated table. The darwin triple's abi is
/// JSON null; the linux triple's abi is a non-null string.
#[test]
fn matrix_napi_and_maturin_share_triple_derivation() {
    use std::process::Command;

    let tmp = tempfile::TempDir::new().unwrap();
    callisto_fixtures::git::init_repo(tmp.path());
    let root = tmp.path();
    std::fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = []\nresolver = \"2\"\n").unwrap();
    std::fs::write(root.join("callisto.toml"), "").unwrap();

    let napi_dir = root.join("napi-mod");
    std::fs::create_dir_all(&napi_dir).unwrap();
    std::fs::write(
        napi_dir.join("package.json"),
        r#"{"name":"napi-mod","napi":{"targets":["aarch64-apple-darwin","x86_64-unknown-linux-gnu"]}}"#,
    )
    .unwrap();

    let maturin_dir = root.join("maturin-mod");
    std::fs::create_dir_all(&maturin_dir).unwrap();
    std::fs::write(
        maturin_dir.join("pyproject.toml"),
        "[project]\nname = \"maturin-mod\"\nversion = \"0.1.0\"\n\n[tool.maturin]\ntargets = [\"aarch64-apple-darwin\", \"x86_64-unknown-linux-gnu\"]\n",
    )
    .unwrap();

    napi_crate(root, "napi-mod");
    let bin = env!("CARGO_BIN_EXE_callisto");
    let output = Command::new(bin)
        .args(["--cwd", &root.to_string_lossy(), "--format", "json", "matrix"])
        .output()
        .expect("failed to spawn callisto binary");

    assert!(
        output.status.success(),
        "matrix should exit 0; stderr: {}",
        String::from_utf8_lossy(&output.stderr)
    );

    let json: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
    let napi_group = &json["platformTargets"]["cargo/napi-mod"];
    let maturin_group = &json["platformTargets"]["pypi/maturin-mod"];
    assert_eq!(napi_group["kind"], "napi");
    assert_eq!(maturin_group["kind"], "maturin");
    assert_eq!(napi_group["source"], "napi.targets");
    assert_eq!(maturin_group["source"], "[tool.maturin].targets");

    let napi_targets = napi_group["targets"].as_array().unwrap();
    let maturin_targets = maturin_group["targets"].as_array().unwrap();
    assert_eq!(napi_targets.len(), 2);
    assert_eq!(maturin_targets.len(), 2);

    for (n, m) in napi_targets.iter().zip(maturin_targets.iter()) {
        assert_eq!(n["triple"], m["triple"]);
        assert_eq!(n["platform"], m["platform"]);
        assert_eq!(n["arch"], m["arch"]);
        assert_eq!(n["abi"], m["abi"]);
        assert_eq!(n["hostRunner"], m["hostRunner"]);
        assert_eq!(n["useCross"], m["useCross"]);

        if n["triple"] == "aarch64-apple-darwin" {
            assert!(n["abi"].is_null(), "darwin abi must serialize as null");
        }
        if n["triple"] == "x86_64-unknown-linux-gnu" {
            assert!(n["abi"].is_string(), "linux abi must be a non-null string");
        }
    }
}

/// Each configured `[[release.artifact]]`
/// cargo binary is a `cargo` platformTargets entry alongside napi entries.
#[test]
fn matrix_lists_release_artifact_cargo_binaries_beside_napi_targets() {
    use std::process::Command;

    let tmp = tempfile::TempDir::new().unwrap();
    callisto_fixtures::git::init_repo(tmp.path());
    let root = tmp.path();
    std::fs::write(
        root.join("Cargo.toml"),
        "[workspace]\nmembers = [\"crates/cli\"]\nresolver = \"2\"\n",
    )
    .unwrap();
    std::fs::create_dir_all(root.join("crates/cli/src")).unwrap();
    std::fs::write(
        root.join("crates/cli/Cargo.toml"),
        "[package]\nname = \"tool\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
    )
    .unwrap();
    std::fs::write(root.join("crates/cli/src/main.rs"), "fn main() {}\n").unwrap();
    std::fs::create_dir_all(root.join("napi-mod")).unwrap();
    std::fs::write(
        root.join("napi-mod/package.json"),
        r#"{"name":"napi-mod","version":"0.1.0","napi":{"targets":["x86_64-unknown-linux-gnu"]}}"#,
    )
    .unwrap();
    std::fs::write(
        root.join("callisto.toml"),
        "[release]\nproduct-package = \"cargo/tool\"\nforge-repository = \"example/tool\"\n\n\
         [[release.artifact]]\npackage = \"cargo/tool\"\ntarget = \"x86_64-unknown-linux-musl\"\nasset-name = \"tool-musl.tar.gz\"\n\n\
         [[release.artifact]]\npackage = \"cargo/tool\"\ntarget = \"aarch64-apple-darwin\"\nasset-name = \"tool-mac.tar.gz\"\n",
    )
    .unwrap();

    napi_crate(root, "napi-mod");
    let output = Command::new(env!("CARGO_BIN_EXE_callisto"))
        .args(["--cwd", &root.to_string_lossy(), "--format", "json", "matrix"])
        .output()
        .expect("failed to spawn callisto binary");
    assert!(
        output.status.success(),
        "stderr: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    let json: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(json["platformTargets"]["cargo/napi-mod"]["kind"], "napi");
    let cargo = &json["platformTargets"]["cargo/tool"];
    assert_eq!(cargo["kind"], "cargo");
    assert_eq!(cargo["source"], "[[release.artifact]]");
    let targets = cargo["targets"].as_array().unwrap();
    assert_eq!(targets.len(), 2, "{cargo}");
    assert_eq!(targets[0]["triple"], "aarch64-apple-darwin");
    assert_eq!(targets[0]["artifactName"], "tool-mac.tar.gz");
    assert_eq!(targets[0]["hostRunner"], "macos-latest");
    assert_eq!(targets[1]["triple"], "x86_64-unknown-linux-musl");
    assert_eq!(targets[1]["artifactName"], "tool-musl.tar.gz");
    assert_eq!(targets[1]["useCross"], true);
    assert_eq!(targets[1]["packageDir"], "crates/cli");
    assert_eq!(targets[1]["packageName"], "tool");
}

/// A cargo `[[release.artifact]]` naming no workspace package is a warning, not a silent drop.
#[test]
fn matrix_warns_on_a_release_artifact_with_an_unknown_package() {
    use std::process::Command;

    let tmp = tempfile::TempDir::new().unwrap();
    callisto_fixtures::git::init_repo(tmp.path());
    let root = tmp.path();
    std::fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = []\nresolver = \"2\"\n").unwrap();
    std::fs::write(
        root.join("callisto.toml"),
        "[release]\nproduct-package = \"cargo/missing\"\nforge-repository = \"example/tool\"\n\n\
         [[release.artifact]]\npackage = \"cargo/missing\"\ntarget = \"x86_64-unknown-linux-gnu\"\nasset-name = \"missing.tar.gz\"\n",
    )
    .unwrap();

