332	            ("inline", "package = { name = \"a\", version = \"1.0.0\" }\n"),
333	            ("dotted", "package.name = \"a\"\n"),
334	        ] {
335	            let dir = tempfile::tempdir().unwrap();
336	            write(dir.path(), "Cargo.toml", manifest);
337	            assert!(is_package_root(dir.path()).unwrap(), "{spelling}");
338	        }
339	    }
