131	        assert!(excluded.is_match(Path::new("packages/a")));
132	        assert!(!excluded.is_match(Path::new("packages/skip")));
133	        assert!(build_globset(&["./".to_string()]).unwrap().is_match(Path::new(".")));
134	    }
