143	/// Workspace-membership filter shared by Cargo's `[workspace]` and uv's
144	/// `[tool.uv.workspace]` -- both use the identical members/exclude
145	/// glob-array shape, including a root manifest that is itself both a
146	/// package/project and a workspace root (hybrid root). `NpmMembership`
147	/// deliberately does NOT go through this type: npm's shape genuinely
148	/// differs (JSON not TOML, no `exclude` concept, and a pnpm-workspace.yaml
149	/// fallback with its own precedence rules).
150	pub(crate) struct Membership {
151	    members: Option<NegatableGlobSet>,
152	    exclude: NegatableGlobSet,
153	    hybrid_root: bool,
154	    /// The manifest has the workspace table, even if it lists no `members`.
155	    declared: bool,
156	}
157	
158	impl Membership {
159	    /// `rel` must be a workspace-relative, forward-slash-normalized path.
160	    /// `is_root` is true exactly when `rel == Path::new(".")`.
161	    pub(crate) fn admits(&self, rel: &Path, is_root: bool) -> bool {
162	        if is_root && self.hybrid_root {
163	            return true;
164	        }
165	        if self.exclude.is_match(rel) {
166	            return false;
167	        }
168	        match &self.members {
169	            None => true,
170	            Some(members) => members.is_match(rel),
171	        }
172	    }
173	
174	    /// Unlike [`Self::admits`], `None` `members` (no `[workspace]` restriction present) never
175	    /// counts here -- only a real `members`/`exclude` glob match, or the hybrid-root case.
176	    pub(crate) fn admits_explicitly(&self, rel: &Path, is_root: bool) -> bool {
177	        if is_root && self.hybrid_root {
178	            return true;
179	        }
180	        match &self.members {
181	            Some(members) => !self.exclude.is_match(rel) && members.is_match(rel),
182	            None => false,
183	        }
184	    }
185	
186	    /// No manifest, or a manifest that declares no workspace restriction: every directory is admitted.
187	    fn unrestricted() -> Self {
188	        Membership {
189	            members: None,
190	            exclude: NegatableGlobSet::empty(),
191	            hybrid_root: false,
192	            declared: false,
193	        }
194	    }
195	}
