197	/// Parses a TOML array-of-strings item, returning `None` for any
198	/// other shape (bare string, table, non-string entries, etc.).
199	fn parse_toml_string_array(item: &toml_edit::Item) -> Option<Vec<String>> {
200	    let arr = item.as_array()?;
201	    let mut out = Vec::with_capacity(arr.len());
202	    for v in arr.iter() {
