303	/// Whether the workspaces nested below `root` admit the package of `ecosystem` at `rel`. The workspace at `root` is
304	/// judged by the `read_*_membership` of each ecosystem; this adds the verdict of a nearer one, which judges the package
305	/// by its own list. `manifest_text` is the package's own manifest.
306	pub(crate) fn nested_workspace_admits(
307	    root: &Path,
308	    rel: &Path,
309	    ecosystem: callisto_model::Ecosystem,
310	    manifest_text: &str,
311	    nested: &mut NestedMemberships,
312	) -> Result<bool, LocateError> {
313	    use callisto_model::Ecosystem;
314	    match ecosystem {
315	        Ecosystem::Cargo => nested_cargo_workspace_admits(root, rel, manifest_text, nested),
316	        Ecosystem::Npm => {
317	            let cache = &mut nested.npm;
318	            judged_by_nearest_declared_workspace(
319	                root,
320	                rel,
321	                cache,
322	                |dir| read_npm_membership(dir).map(|membership| membership.globs.is_some().then_some(membership)),
323	                |membership, within| membership.admits(within, false),
324	            )
325	        }
326	        Ecosystem::Pypi => {
327	            let cache = &mut nested.python;
328	            judged_by_nearest_declared_workspace(
329	                root,
330	                rel,
331	                cache,
332	                |dir| read_python_membership(dir).map(|membership| membership.declared.then_some(membership)),
333	                |membership, within| membership.admits(within, false),
334	            )
335	        }
336	        _ => Ok(true),
337	    }
338	}
