583	/// Applies `[[package]]` and `[[package-set]]` rules to each identified package, then reports rules that matched
584	/// nothing or matched across ecosystems.
585	fn resolve_packages(
586	    package_manifest_decls: BTreeMap<PackageId, (PathBuf, Vec<ManifestDecl>)>,
587	    index: &IdentityIndex,
588	    cfg: &ResolvedConfig,
589	    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
590	    ctx: &OpenContext<'_>,
591	    diagnostics: &mut Vec<Diagnostic>,
592	) -> Result<BTreeMap<PackageId, Package>, GraphError> {
593	    prewarm_manifests(&package_manifest_decls, manifest_cache, ctx);
594	
595	    // Tracks, per cfg.package_sets entry (by index), whether it matched at
596	    // least one real discovered package during this walk. A [[package-set]]
597	    // rule that matches nothing is almost always a typo or a stale
598	    // ecosystem prefix (see PackageSetMatchedNothing below) rather than
599	    // intentional, so it must be surfaced instead of silently ignored.
600	    let mut package_set_matched = vec![false; cfg.package_sets.len()];
601	
602	    // Same tracking, for `[[package]]` rules: an exact-id rule that matches zero real
603	    // packages (e.g. an ecosystem prefix the package doesn't actually have) is just as
604	    // likely a typo as an empty `[[package-set]]` glob, so it gets the same diagnostic.
605	    let mut package_rule_matched = vec![false; cfg.packages.len()];
606	    let mut package_rule_hint: Vec<Option<String>> = vec![None; cfg.packages.len()];
607	
608	    let mut packages = BTreeMap::new();
609	    for (id, (rel_path, decls)) in package_manifest_decls {
610	        let ch_path = rel_path.join("CHANGELOG.md");
611	        let mut publish_to = Vec::new();
612	        // Attached platform manifests publish as their owner's platform operations, not as targets.
613	        for decl in decls.iter().filter(|d| d.role == ManifestRole::Canonical) {
614	            match open_cached(manifest_cache, decl, ctx) {
615	                Ok(editor) => {
616	                    for target in editor.publish_targets() {
617	                        if target != PublishTarget::None && !publish_to.contains(&target) {
618	                            publish_to.push(target);
619	                        }
620	                    }
621	                }
622	                Err(error) => diagnostics.push(unresolved(
623	                    &decl.path,
624	                    "open its manifest to read its publish targets",
625	                    error,
626	                )),
627	            }
628	        }
629	        if publish_to.is_empty() {
630	            publish_to.push(PublishTarget::None);
631	        }
632	
633	        // The real ecosystem(s) this package's manifests were discovered
634	        // in. `id` may be PackageId::Bare (unpromoted) or PackageId::Prefixed
635	        // (promoted); this is the
636	        // only place an ecosystem-prefixed [[package-set]] pattern has
637	        // anything to match against.
638	        let package_ecosystems: Vec<Ecosystem> = decls.iter().map(|d| d.ecosystem()).collect();
639	
640	        // The first [[package]] rule, in declaration order, whose ecosystem this package has and whose name matches.
641	        let native_names: Vec<(Ecosystem, &str)> = index.native_names(&id).collect();
642	        let pkg_override = resolve_package_config(&native_names, cfg);
643	
644	        // Record which [[package-set]] patterns match this package,
645	        // independent of whether a [[package]] rule ends up shadowing the
646	        // fallback below — a pattern that is always shadowed still
647	        // "matched" for the purpose of the zero-match diagnostic.
648	        for (idx, (pattern, _)) in cfg.package_sets.iter().enumerate() {
649	            if pattern.matches_native(&native_names) {
650	                package_set_matched[idx] = true;
651	            }
652	        }
653	        for (idx, (rule_id, _)) in cfg.packages.iter().enumerate() {
654	            if rule_applies(rule_id, &native_names) {
655	                package_rule_matched[idx] = true;
656	            } else if package_rule_hint[idx].is_none() {
657	                package_rule_hint[idx] = index.suggest_native(&rule_id.to_string());
658	            }
659	        }
660	
661	        // If no [[package]] rule matched, look for a [[package-set]] fallback.
662	        // [[package-set]] uses glob patterns and can match many packages at once;
663	        // [[package]] always takes priority over [[package-set]] for the same package.
664	        let set_override = if pkg_override.is_none() {
665	            cfg.package_sets
666	                .iter()
667	                .find(|(pattern, _)| pattern.matches_native(&native_names))
668	                .map(|(_, cfg)| cfg)
669	        } else {
670	            None
671	        };
672	
673	        let active_override = pkg_override.or(set_override);
674	
675	        // Single source of truth for the default: ReleaseTrigger's #[default].
676	        let release_trigger = active_override.and_then(|o| o.release_trigger).unwrap_or_default();
677	
678	        let tag_template = active_override.and_then(|o| o.tag_template.clone());
679	
680	        let changelog = if let Some(override_path) = active_override.and_then(|o| o.changelog.as_ref()) {
681	            Some(rel_path.join(override_path))
682	        } else {
683	            Some(ch_path)
684	        };
685	
686	        // Apply the resolved override's publish-to if the operator explicitly set it.
687	        //
688	        // A `[[package]]`/`[[package-set]]` rule has no package context at
689	        // config-parse time (it's just a pattern + string list), so the
690	        // only place the package's real, detected ecosystem is known is
691	        // here, once `decls` (the package's actual manifests) have been
692	        // walked. Reject any configured target whose `.ecosystem()` does
693	        // not match one of the package's detected ecosystems — e.g.
694	        // `publish-to = ["nuget"]` on a Cargo-only crate — rather than
695	        // silently accepting it and having the crate vanish from every
696	        // real publish downstream with zero diagnostic.
697	        if let Some(override_targets) = active_override.and_then(|o| o.publish_to.as_deref()) {
698	            for target in override_targets {
699	                if let Some(target_ecosystem) = target.ecosystem()
700	                    && !package_ecosystems.contains(&target_ecosystem)
701	                {
702	                    return Err(GraphError::PublishTargetEcosystemMismatch {
703	                        package: id.clone(),
704	                        target: target.config_str().to_string(),
705	                        target_ecosystem,
706	                        package_ecosystems,
707	                    });
708	                }
709	            }
710	            // The override replaces *which* targets the package publishes
711	            // to, but must not silently drop manifest-derived fields
712	            // (npm publishConfig.access/registry) the config itself
713	            // didn't set -- config wins when explicit, manifest fills gaps.
714	            publish_to = override_targets
715	                .iter()
716	                .map(|target| {
717	                    let manifest_target = target
718	                        .ecosystem()
719	                        .and_then(|eco| publish_to.iter().find(|m| m.ecosystem() == Some(eco)));
720	                    match manifest_target {
721	                        Some(manifest_target) => target.clone().merge_manifest_gaps(manifest_target),
722	                        None => target.clone(),
723	                    }
724	                })
725	                .collect();
726	        }
727	
728	        let pkg = Package {
729	            id: id.clone(),
730	            manifests: decls,
731	            changelog,
732	            release_trigger,
733	            publish_to,
734	            tag_template,
735	        };
736	        packages.insert(id, pkg);
737	    }
738	
739	    // A [[package-set]] rule that matched zero real packages is almost
740	    // always a mistake (e.g. an ecosystem prefix that doesn't correspond
741	    // to any discovered package, or a typo in the glob) rather than
742	    // intentional, so surface it as a visible, non-fatal diagnostic
743	    // instead of letting the rule silently do nothing. This is
744	    // deliberately advisory rather than a hard `GraphError`: a
745	    // `[[package-set]]` rule declared for a monorepo-wide callisto.toml
746	    // can legitimately match nothing when only part of the workspace is
747	    // present (e.g. a partial checkout or filtered walk), and a hard
748	    // error would break that case.
749	    for (idx, (pattern, _)) in cfg.package_sets.iter().enumerate() {
750	        if !package_set_matched[idx] {
751	            diagnostics.push(Diagnostic {
752	                code: DiagnosticCode::PackageSetMatchedNothing,
753	                severity: DiagnosticSeverity::Warning,
754	                message: format!("[[package-set]] `{}` matched no packages", pattern.as_str()),
755	                package: None,
756	                path: None,
757	                escalated_by: None,
758	                governed_by: None,
759	            });
760	        }
761	    }
762	
763	    // A [[package]] rule that matched zero real packages is the same kind of mistake as an
764	    // empty [[package-set]] match above (e.g. `cargo/foo` when `foo` only exists in npm) --
765	    // advisory for the same reason: a monorepo-wide callisto.toml against a partial checkout
766	    // can legitimately match nothing.
767	    for (idx, (rule_id, _)) in cfg.packages.iter().enumerate() {
768	        if !package_rule_matched[idx] {
769	            diagnostics.push(Diagnostic {
770	                code: DiagnosticCode::PackageRuleMatchedNothing,
771	                severity: DiagnosticSeverity::Warning,
772	                message: match &package_rule_hint[idx] {
773	                    Some(hint) => format!("[[package]] `{rule_id}` matched no packages; did you mean `{hint}`?"),
774	                    None => format!("[[package]] `{rule_id}` matched no packages"),
775	                },
776	                package: None,
777	                path: None,
778	                escalated_by: None,
779	                governed_by: None,
780	            });
781	        }
782	    }
783	
784	    Ok(packages)
785	}
