789	/// One edge per dependency declaration of each canonical manifest that resolves to a workspace package.
790	fn build_edges(
791	    root: &Path,
792	    packages: &BTreeMap<PackageId, Package>,
793	    index: &IdentityIndex,
794	    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
795	    ctx: &OpenContext<'_>,
796	    diagnostics: &mut Vec<Diagnostic>,
797	) -> (Vec<DepEdge>, EdgeIndex, EdgeIndex) {
798	    let mut edges = Vec::new();
799	    let mut out_index: BTreeMap<PackageId, Vec<usize>> = BTreeMap::new();
800	    let mut in_index: BTreeMap<PackageId, Vec<usize>> = BTreeMap::new();
801	
802	    for pkg in packages.values() {
803	        for decl in &pkg.manifests {
804	            if decl.role != ManifestRole::Canonical {
805	                continue;
806	            }
807	            let m = match open_cached(manifest_cache, decl, ctx) {
808	                Ok(m) => m,
809	                Err(error) => {
810	                    diagnostics.push(unresolved(
811	                        &decl.path,
812	                        "open its manifest to read its dependencies",
813	                        error,
814	                    ));
815	                    continue;
816	                }
817	            };
818	            {
819	                for entry in m.iter_dependencies() {
820	                    let inherited = entry.inherited.then(|| m.inherited_dependency(&entry.name)).flatten();
821	                    let (spec, declaring_path) = match inherited {
822	                        Some(dep) => (dep.spec.clone(), dep.declared_in.to_path_buf()),
823	                        None => (entry.spec.clone(), decl.path.clone()),
824	                    };
825	
826	                    let workspace_target = match &spec {
827	                        DepSpec::WorkspaceProtocol(workspace) => workspace.relative_path().and_then(|relative| {
828	                            relative_workspace_package(root, &decl.path, relative, packages.values()).unwrap_or_else(
829	                                |error| {
830	                                    diagnostics.push(unresolved(
831	                                        &decl.path,
832	                                        "resolve a relative `workspace:` dependency",
833	                                        error,
834	                                    ));
835	                                    None
836	                                },
837	                            )
838	                        }),
839	                        _ => None,
840	                    };
841	                    let to = match &spec {
842	                        DepSpec::WorkspaceProtocol(workspace) if workspace.relative_path().is_some() => {
843	                            workspace_target
844	                        }
845	                        _ => workspace_target.or_else(|| {
846	                            index
847	                                .resolve_native_with_fallback(decl.ecosystem(), &entry.package_name, diagnostics)
848	                                .cloned()
849	                        }),
850	                    };
851	                    if let Some(to) = to {
852	                        let idx = edges.len();
853	                        let edge = DepEdge {
854	                            from: pkg.id.clone(),
855	                            to: to.clone(),
856	                            name: entry.name,
857	                            kind: entry.kind,
858	                            spec,
859	                            from_manifest: declaring_path,
860	                            inherited: entry.inherited,
861	                            locator: entry.locator,
862	                        };
863	                        edges.push(edge);
864	
865	                        out_index.entry(pkg.id.clone()).or_default().push(idx);
866	                        in_index.entry(to).or_default().push(idx);
867	                    } else if matches!(&spec, DepSpec::WorkspaceProtocol(workspace) if workspace.relative_path().is_some())
868	                    {
869	                        diagnostics.push(Diagnostic {
870	                                code: DiagnosticCode::UnknownPackage,
871	                                severity: DiagnosticSeverity::Warning,
872	                                message: format!(
873	                                    "relative pnpm workspace dependency `{}` from `{}` does not identify an admitted npm workspace member",
874	                                    entry.name,
875	                                    decl.path.display()
876	                                ),
877	                                package: Some(pkg.id.clone()),
878	                                path: Some(decl.path.clone()),
879	                                escalated_by: None,
880	                                governed_by: None,
881	                            });
882	                    }
883	                }
884	            }
885	        }
886	    }
887	
888	    (edges, out_index, in_index)
889	}
