891	/// Maps each npm-only platform package directory (`os`+`cpu`)
892	/// to the owner directory whose `package.json` names it in `optionalDependencies`,
893	/// plus the platform's own name and role. `non_members` are platform packages
894	/// outside the npm workspace, attachable but otherwise not discovered. A member
895	/// platform named by no owner, or by more than one, stays its own package with a
896	/// diagnostic.
897	fn platform_owners(
898	    root: &Path,
899	    by_path: &BTreeMap<PathBuf, Vec<(Ecosystem, PackageId)>>,
900	    non_members: &[callisto_model::ProjectRoot],
901	    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
902	    ctx: &OpenContext<'_>,
903	    diagnostics: &mut Vec<Diagnostic>,
904	) -> BTreeMap<PathBuf, (PathBuf, String, ManifestRole)> {
905	    let open_npm = |rel_path: &Path| -> Result<Arc<dyn Manifest>, Diagnostic> {
906	        let manifest_rel = rel_path.join("package.json");
907	        let decl = ManifestDecl::new(
908	            manifest_rel.clone(),
909	            ManifestRole::Canonical,
910	            ManifestFormat::PackageJson,
911	        )
912	        .map_err(|error| unresolved(&manifest_rel, "declare its manifest", error))?;
913	        open_cached(manifest_cache, &decl, ctx)
914	            .map_err(|error| unresolved(&manifest_rel, "open its manifest to read its platform role", error))
915	    };
916	    let platform_role = |manifest: &Arc<dyn Manifest>| match manifest.npm_role()? {
917	        callisto_manifests::NpmRole::Platform { platform, arch, abi } => {
918	            Some(ManifestRole::Platform { platform, arch, abi })
919	        }
920	    };
921	
922	    let mut platforms = Vec::new();
923	    let mut owners_of: BTreeMap<String, Vec<PathBuf>> = BTreeMap::new();
924	    for (rel_path, list) in by_path {
925	        let Some((_, id)) = list.iter().find(|(eco, _)| *eco == Ecosystem::Npm) else {
926	            continue;
927	        };
928	        let manifest = match open_npm(rel_path) {
929	            Ok(manifest) => manifest,
930	            Err(problem) => {
931	                diagnostics.push(problem);
932	                continue;
933	            }
934	        };
935	        // A co-located platform manifest already belongs to its directory's package.
936	        match platform_role(&manifest) {
937	            Some(role) if list.len() == 1 => platforms.push((rel_path.clone(), id.name().to_string(), role, true)),
938	            _ => {
939	                for dep in manifest.iter_dependencies() {
940	                    if dep.kind == callisto_model::DepKind::Optional {
941	                        owners_of.entry(dep.name).or_default().push(rel_path.clone());
942	                    }
943	                }
944	            }
945	        }
946	    }
947	    for candidate in non_members {
948	        if by_path.contains_key(&candidate.path) {
949	            continue;
950	        }
951	        // A Cargo/Python package physically sits beside this candidate's package.json even
952	        // though it wasn't discovered as a workspace member here (e.g. filtered out by that
953	        // ecosystem's own membership) -- attaching it as a bare platform manifest would
954	        // misattach a directory that already hosts a real, distinct package.
955	        let beside = |name: &str| callisto_model::strict_fs::exists(&root.join(&candidate.path).join(name));
956	        match (beside("Cargo.toml"), beside("pyproject.toml")) {
957	            (Ok(false), Ok(false)) => {}
958	            (Err(error), _) | (_, Err(error)) => {
959	                diagnostics.push(unresolved(
960	                    &candidate.path,
961	                    "check whether another package shares its directory",
962	                    error,
963	                ));
964	                continue;
965	            }
966	            _ => continue,
967	        }
968	        let role = match open_npm(&candidate.path) {
969	            Ok(manifest) => platform_role(&manifest),
970	            Err(problem) => {
971	                diagnostics.push(problem);
972	                None
973	            }
974	        };
975	        if let Some(role) = role {
976	            platforms.push((candidate.path.clone(), candidate.id.name().to_string(), role, false));
977	        }
978	    }
979	
980	    let mut attached = BTreeMap::new();
981	    for (rel_path, name, role, member) in platforms {
982	        match owners_of.get(&name).map(Vec::as_slice) {
983	            Some([owner]) => {
984	                attached.insert(rel_path, (owner.clone(), name, role));
985	            }
986	            None if !member => {}
987	            owners => {
988	                let reason = match owners {
989	                    Some(owners) => format!(
990	                        "is named in the optionalDependencies of {} packages ({})",
991	                        owners.len(),
992	                        owners
993	                            .iter()
994	                            .map(|p| p.display().to_string())
995	                            .collect::<Vec<_>>()
996	                            .join(", ")
997	                    ),
998	                    None => "is not named in any npm package's optionalDependencies".to_string(),
999	                };
1000	                diagnostics.push(Diagnostic {
1001	                    code: DiagnosticCode::PlatformPackageWithoutOwner,
1002	                    severity: DiagnosticSeverity::Warning,
1003	                    message: format!(
1004	                        "npm platform package `{name}` {reason}; {}",
1005	                        if member {
1006	                            "it is released as its own package instead of as a platform manifest of its owner"
1007	                        } else {
1008	                            "it is outside the npm workspace, so it is not released at all"
1009	                        }
1010	                    ),
1011	                    package: None,
1012	                    path: Some(rel_path.join("package.json")),
1013	                    escalated_by: None,
1014	                    governed_by: None,
1015	                });
1016	            }
1017	        }
1018	    }
1019	    attached
1020	}
