150	    if current.major() != Some(0) || current.minor() == Some(0) || !has_prior_release {
151	        return (inferred, false);
152	    }
153	
154	    match (policy, inferred) {
155	        (PreMajorInferencePolicy::Conservative | PreMajorInferencePolicy::ConservativeFeat, Severity::Major) => {
156	            (Severity::Minor, true)
157	        }
158	        (PreMajorInferencePolicy::ConservativeFeat, Severity::Minor) => (Severity::Patch, true),
159	        (_, s) => (s, false),
160	    }
